-- Persistent learning state. Ultra VIS remains the source of truth for study,
-- while a compact, private summary is mirrored to the linked SkillLand profile.
ALTER TABLE users ADD COLUMN skillland_sync_token TEXT DEFAULT '';
ALTER TABLE users ADD COLUMN skillland_role TEXT DEFAULT 'student';
ALTER TABLE users ADD COLUMN skillland_headline TEXT DEFAULT '';

CREATE TABLE IF NOT EXISTS lecture_progress (
  user_id INTEGER NOT NULL,
  lecture_id INTEGER NOT NULL,
  progress INTEGER NOT NULL DEFAULT 0 CHECK(progress >= 0 AND progress <= 100),
  completed_at TEXT,
  last_opened_at TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id, lecture_id),
  FOREIGN KEY (user_id) REFERENCES users(id),
  FOREIGN KEY (lecture_id) REFERENCES lectures(id)
);

CREATE INDEX IF NOT EXISTS idx_lecture_progress_user_recent ON lecture_progress(user_id, last_opened_at DESC);

CREATE TABLE IF NOT EXISTS quiz_results (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  primary_direction TEXT NOT NULL,
  secondary_direction TEXT DEFAULT '',
  summary TEXT NOT NULL,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id)
);

CREATE INDEX IF NOT EXISTS idx_quiz_results_user_recent ON quiz_results(user_id, id DESC);

UPDATE lectures SET
  title = 'Линейная алгебра: векторы и пространство',
  description = 'Понятный вход в векторы, матрицы и модели, которыми описывают движение, данные и графику.',
  author = 'SkillLand Studio', duration = 52,
  image = '/assets/images/lectures/lecture-math-linear-v1.png',
  content = 'Зачем это нужно\nВектор — это не набор скучных чисел, а способ честно описать направление и величину. Так работают навигаторы, игровая графика, рекомендации и машинное обучение.\n\n1. Координаты и направление\nПредставь путь от дома до университета. Два числа говорят, куда сдвинуться по горизонтали и вертикали. Это и есть вектор. Его можно складывать: один путь после другого становится новым путём.\n\n2. Длина вектора\nДлина показывает силу или расстояние. Для вектора (x, y) она равна корню из x² + y². Не нужно запоминать это вслепую: это обычная теорема Пифагора на координатной плоскости.\n\n3. Матрица как правило преобразования\nМатрица получает вектор и возвращает новый. Ею можно повернуть объект, растянуть фотографию или преобразовать набор признаков в модели данных. Важна не таблица сама по себе, а правило изменения.\n\nПример\nВектор (3, 4) имеет длину 5. Если добавить к нему (1, -2), получится (4, 2): объект сместился вправо и вниз.\n\nМини-практика\nНарисуй два вектора на клетчатой бумаге, сложи их по правилу «из конца в начало» и объясни итог одной фразой.\n\nЧто запомнить\nВекторы описывают направление, матрицы меняют пространство, а алгебра становится понятной, когда у каждого числа есть геометрический смысл.',
  level = 'Начальный' WHERE id = 1;

UPDATE lectures SET
  title = 'Квантовая физика без тумана',
  description = 'Спокойно разбираем вероятность, наблюдение и то, почему квантовые эффекты уже есть в технологиях.',
  author = 'д-р Майя Чен', duration = 48,
  image = '/assets/images/lectures/lecture-physics-quantum-v1.png',
  content = 'Главная идея\nВ квантовом мире мы не всегда получаем один заранее записанный ответ. Часто физика говорит о вероятностях: какие результаты возможны и насколько каждый из них вероятен.\n\n1. Не «магия», а масштаб\nАтомы и электроны настолько малы, что привычные правила движения работают иначе. Это не отменяет логику — просто её язык становится вероятностным.\n\n2. Состояние и измерение\nДо измерения система описывается набором возможных результатов. Измерение даёт один конкретный результат. Важно: наблюдение здесь — это физическое взаимодействие с прибором, а не сила мысли человека.\n\n3. Волна и частица\nСвет и электроны могут проявлять разные свойства в разных опытах. Хорошая аналогия: один объект отвечает на разные вопросы разными наблюдаемыми характеристиками.\n\nГде это встречается\nЛазеры, полупроводники, медицинская томография и будущие квантовые вычисления опираются на квантовые эффекты.\n\nМини-практика\nСформулируй разницу между «мы не знаем ответ» и «у системы есть несколько вероятных ответов до измерения».\n\nЧто запомнить\nКвантовая физика не требует верить в парадоксы. Она учит описывать малые системы точнее, чем позволяет бытовая интуиция.',
  level = 'Средний' WHERE id = 2;

UPDATE lectures SET
  title = 'JavaScript: первый живой интерфейс',
  description = 'Собери интерфейс, который реагирует на действия: переменные, события и DOM без лишней теории.',
  author = 'Алекс Ким', duration = 58,
  image = '/assets/images/lectures/lecture-programming-v1.png',
  content = 'Что ты сделаешь\nК концу лекции у тебя будет простая кнопка, которая меняет текст на странице. Внутри этого действия уже живут три основы JavaScript: данные, условия и события.\n\n1. Переменная\nПеременная хранит значение. Например, let progress = 0; создаёт место для счётчика. Имя должно отвечать на вопрос «что лежит внутри».\n\n2. Событие\nСтраница не делает всё сразу. Она ждёт: клик, ввод текста, отправку формы. addEventListener связывает действие человека с функцией в коде.\n\n3. DOM\nDOM — это представление HTML как дерева объектов. Через document.querySelector ты находишь нужный элемент и меняешь его текст, класс или атрибут.\n\nПример\nНайди кнопку, подпиши обработчик клика и увеличивай счётчик на 1. После каждого клика выводи новое число рядом.\n\nЧастая ошибка\nКод ищет элемент до того, как страница его создала. Решение: подключай скрипт в конце body или используй событие DOMContentLoaded.\n\nМини-практика\nСделай две кнопки: «увеличить» и «сбросить». Не копируй код, а назови своими словами, что делает каждая строка.\n\nЧто запомнить\nИнтерфейс становится живым, когда код слушает событие, меняет данные и заново показывает их человеку.',
  level = 'Начальный' WHERE id = 3;

UPDATE lectures SET
  title = 'Python для реальных задач',
  description = 'На простых примерах разбираем ввод, условия, циклы и данные — от идеи до полезного сценария.',
  author = 'Нора Дэвис', duration = 55,
  image = '/assets/images/lectures/lecture-programming-python-v1.png',
  content = 'Почему Python\nPython читается почти как обычный текст. Поэтому на нём удобно учиться разбирать задачу на шаги, автоматизировать рутину и работать с данными.\n\n1. Ввод и переменные\ninput получает текст от человека. Переменная сохраняет результат, чтобы использовать его дальше. Если нужен расчёт, строку можно превратить в число через int или float.\n\n2. Условия\nif помогает программе выбрать действие. Например: если задача выполнена, добавь её в список достижений; иначе покажи следующий шаг.\n\n3. Циклы\nЦикл повторяет действие для каждого элемента. Это удобно, когда нужно проверить список, посчитать результаты опроса или обработать таблицу.\n\nПример\nЕсть список оценок. Пройди по нему циклом, сложи значения и раздели на количество — получится среднее.\n\nКак думать\nСначала запиши решение человеческими шагами. Потом каждый шаг преврати в одну-две строки кода. Это надёжнее, чем искать «правильный» готовый кусок.\n\nМини-практика\nНапиши программу, которая спрашивает имя и цель на неделю, а затем выводит персональное напоминание.\n\nЧто запомнить\nPython нужен не для запоминания команд. Он помогает точно формулировать действия и сразу проверять идею результатом.',
  level = 'Начальный' WHERE id = 4;

UPDATE lectures SET
  title = 'Живая клетка: система внутри нас',
  description = 'Понимаем, как клетка получает энергию, общается и поддерживает жизнь организма.',
  author = 'д-р София Грин', duration = 46,
  image = '/assets/images/lectures/lecture-biology-cell-v1.png',
  content = 'Клетка как город\nУ клетки есть граница, источник энергии, система производства и доставки. Такая аналогия помогает увидеть не набор терминов, а работающую систему.\n\n1. Мембрана\nМембрана решает, что впустить и что выпустить. Она не просто оболочка: через неё идут сигналы, вода, питательные вещества и ионы.\n\n2. Энергия\nМитохондрии помогают извлекать энергию из питательных веществ. Это не «батарейки», а маленькие станции с цепочкой химических реакций.\n\n3. Инструкция\nДНК хранит информацию, а РНК помогает использовать отдельные инструкции для создания белков. Белки затем строят структуры и запускают процессы.\n\nПример\nКогда мышце нужна энергия, клетки получают сигнал, ускоряют нужные реакции и используют запасённые вещества. Все этапы согласованы во времени.\n\nМини-практика\nНарисуй клетку и подпиши три части: граница, энергия, инструкция. Рядом напиши функцию каждой простыми словами.\n\nЧто запомнить\nЖизнь работает не благодаря одному органоиду, а благодаря точной связи между многими небольшими системами.',
  level = 'Начальный' WHERE id = 5;

UPDATE lectures SET
  title = 'Органическая химия: видеть закономерности',
  description = 'Учимся узнавать структуры и реакции, которые стоят за материалами, лекарствами и привычными вещами.',
  author = 'Иван Петров', duration = 51,
  image = '/assets/images/lectures/lecture-chemistry-organic-v1.png',
  content = 'С чего начать\nОрганическая химия кажется огромной, пока молекулы не превращаются в понятные строительные блоки. Сначала ищи углеродный каркас, затем функциональную группу.\n\n1. Каркас\nАтомы углерода могут соединяться в цепочки и кольца. Длина и форма каркаса уже меняют свойства вещества.\n\n2. Функциональные группы\nНебольшие фрагменты вроде спиртовой или карбоксильной группы определяют типичные реакции. Это как знакомая деталь в разных конструкциях.\n\n3. Реакция как перестройка\nВ реакции связи разрываются и образуются. Важно отслеживать, какая часть молекулы изменилась и почему условия опыта это позволяют.\n\nПример\nЭтанол и уксусная кислота содержат углерод, но разные функциональные группы делают один спиртом, а другую кислотой.\n\nБезопасность мышления\nНе пытайся угадывать реакцию по картинке. Назови исходные вещества, условия и ожидаемое изменение — тогда ответ проверяем.\n\nМини-практика\nВыбери две бытовые молекулы: например, сахар и уксус. Найди, какие атомы и группы можно распознать в их формулах.\n\nЧто запомнить\nОрганическая химия становится предсказуемой, когда ты видишь повторяющиеся фрагменты, а не запоминаешь тысячи отдельных формул.',
  level = 'Средний' WHERE id = 6;

UPDATE lectures SET
  title = 'Микроэкономика в ежедневных решениях',
  description = 'Цена, выбор и стимулы — на жизненных примерах, без перегруженных графиков.',
  author = 'Лена Моррис', duration = 43,
  image = '/assets/images/lectures/lecture-economics-micro-v1.png',
  content = 'Экономика — это выбор\nМикроэкономика изучает решения людей, компаний и рынков, когда ресурсов и времени всегда меньше, чем желаний.\n\n1. Альтернативная стоимость\nВыбирая одно, мы отказываемся от другого. Если вечером ты готовишься к экзамену, стоимость этого решения — не деньги, а время, которое не ушло на отдых или работу.\n\n2. Спрос и предложение\nКогда товар нужен многим, а его мало, цена обычно растёт. Когда предложений больше, чем желающих купить, продавцам приходится снижать цену или улучшать условия.\n\n3. Стимулы\nЛюди реагируют на выгоду, риск, удобство и правила. Хорошая модель не обвиняет человека, а спрашивает: какие стимулы он видит?\n\nПример\nКофейня может снизить цену вечером, чтобы не списывать продукты. Покупатель получает выгоду, а бизнес уменьшает потери — обе стороны меняют решение.\n\nМини-практика\nОпиши один свой выбор за неделю. Назови альтернативу, цену решения и стимул, который на него повлиял.\n\nЧто запомнить\nЭкономика помогает не предсказывать каждого человека, а яснее видеть последствия выбора и ограничения ситуации.',
  level = 'Начальный' WHERE id = 7;

UPDATE lectures SET
  title = 'История России: видеть поворотные точки',
  description = 'Связываем события, людей и идеи в последовательность, а не в список дат для заучивания.',
  author = 'Андрей Волков', duration = 57,
  image = '/assets/images/lectures/lecture-history-russia-v1.png',
  content = 'Как изучать историю\nИстория — это не только «что случилось». Полезнее держать три вопроса: какие были условия, кто принимал решения и к чему они привели.\n\n1. Причина и повод\nПричины формируются долго: экономические условия, устройство власти, идеи общества. Повод запускает событие здесь и сейчас. Их нельзя смешивать.\n\n2. Несколько точек зрения\nОдин и тот же период по-разному выглядел для горожанина, крестьянина, чиновника или солдата. Источник всегда нужно читать с вопросом: кто его создал и зачем.\n\n3. Последствия\nУ события бывают ближайшие и долгие последствия. Важно не только назвать реформу или конфликт, но и увидеть, какие институты, привычки и споры они изменили.\n\nПример\nРеформа может решить одну задачу и создать новую. Поэтому исторический анализ не заканчивается в год принятия закона.\n\nМини-практика\nВыбери одну поворотную точку из своей программы и составь цепочку: условия → решение → реакция общества → последствия.\n\nЧто запомнить\nХорошее историческое объяснение показывает связи. Даты в нём помогают ориентироваться, но не заменяют смысл.',
  level = 'Начальный' WHERE id = 8;

UPDATE lectures SET
  title = 'Английский для идей и презентаций',
  description = 'Собираем ясную структуру выступления и лексику, чтобы доносить мысль спокойно и убедительно.',
  author = 'Оливия Брукс', duration = 39,
  image = '/assets/images/lectures/lecture-languages-english-v1.png',
  content = 'Цель — понятность\nХорошая презентация на английском не требует сложных слов. Ей нужны логика, короткие фразы и понятный переход от одной мысли к другой.\n\n1. Открой тему\nНачни с того, о чём будет разговор и почему это важно: Today I want to show… Затем назови две-три части, которые ждут слушателя.\n\n2. Объясни идею\nОдна мысль — один абзац. Используй простые связки: first, however, because of this, for example. Они помогают слушателю не потерять логику.\n\n3. Сделай вывод\nВ конце повтори главный вывод другими словами и предложи следующий шаг: The key point is… / The next step is…\n\nПроизношение\nНе стремись звучать как носитель. Говори чуть медленнее, ставь паузы и заранее потренируй слова, в которых часто ошибаешься.\n\nМини-практика\nПодготовь 60-секундное выступление о своей идее: проблема, решение, один пример, вывод. Запиши себя и отметь одно место, которое можно упростить.\n\nЧто запомнить\nУверенная речь рождается из структуры. Когда мысль ясна тебе, её легче услышать на любом языке.',
  level = 'Начальный' WHERE id = 9;

UPDATE lectures SET
  title = 'Этика: задавать более точные вопросы',
  description = 'Разбираем сложный выбор через последствия, принципы и уважение к людям, а не через готовые ответы.',
  author = 'Михаил Орлов', duration = 45,
  image = '/assets/images/lectures/lecture-philosophy-ethics-v1.png',
  content = 'Что делает вопрос этическим\nЭтика начинается там, где решение влияет на других людей и где разумных аргументов может быть несколько. Её задача — не выдать один правильный ответ, а сделать выбор честным и объяснимым.\n\n1. Последствия\nСпроси: кому станет лучше или хуже, каков масштаб вреда и есть ли более мягкий вариант? Этот подход полезен, когда нужно сравнить результаты действий.\n\n2. Принципы\nНекоторые вещи важны сами по себе: не обманывать, уважать достоинство, не использовать человека только как средство. Принципы удерживают от удобных, но разрушительных решений.\n\n3. Справедливость\nПроверь, не меняется ли правило в зависимости от того, кто получает выгоду. Хороший тест: согласился бы ты на это правило, не зная, в какой роли окажешься?\n\nПример\nКоманда выбирает, публиковать ли данные пользователей. Нужно рассмотреть пользу продукта, согласие людей, риски утечки и более безопасные альтернативы.\n\nМини-практика\nВозьми один реальный выбор и запиши по одному аргументу через последствия, принципы и справедливость. Затем найди, где аргументы спорят друг с другом.\n\nЧто запомнить\nЭтическое мышление не делает выбор лёгким. Оно делает его прозрачным, уважительным и готовым к проверке аргументами.',
  level = 'Средний' WHERE id = 10;
